import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BankCinematicProps = Record<string, any>;

const BankCinematic: React.FC<BankCinematicProps> = ({
  backgroundColor = "#050505",
  primaryColor = "#ffed3d",
  transparentBackground = false,
  durationInSeconds = 8,
  zoomIntensity = 0.15,
  bankSize = 400,
}) => {
  // 1. Load Font
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // 2. Parser Safety for Colors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 3. Animation Logic

  // A. Global Cinematic Zoom
  // Interpolates continuously over the entire duration
  const scale = interpolate(
    frame,
    [0, durationInFrames],
    [1, 1 + zoomIntensity],
    {
      easing: Easing.bezier(0.25, 1, 0.5, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // B. Bank Entrance (Spring from bottom)
  const bankEntrance = spring({
    frame: frame - 15, // Delay start by 15 frames
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 1,
    },
  });

  const bankTranslateY = interpolate(bankEntrance, [0, 1], [height * 0.3, 0]);
  const bankOpacity = interpolate(bankEntrance, [0, 1], [0, 1]);

  // C. Text Entrance (Staggered after bank)
  const textEntrance = spring({
    frame: frame - 35, // Delay start by 35 frames
    fps,
    config: {
      damping: 14,
      stiffness: 80,
    },
  });

  const textTranslateY = interpolate(textEntrance, [0, 1], [40, 0]);
  const textOpacity = interpolate(textEntrance, [0, 1], [0, 1]);

  // Dynamic Sizing based on bankSize prop and viewport
  const iconSize = Math.min(bankSize, width * 0.8);
  const fontSize = iconSize * 0.2; // Text relative to icon

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        overflow: "hidden", // Important for zoom effect not to cause scrollbars/overflow issues if embedded
      }}
    >
      {/* Zoom Container */}
      <AbsoluteFill
        style={{
          transform: `scale(${scale})`,
          justifyContent: "center",
          alignItems: "center",
          display: "flex",
          flexDirection: "column",
          gap: iconSize * 0.1, // Gap between icon and text
          transition: "none",
        }}
      >
        {/* Bank Icon Container */}
        <div
          style={{
            width: iconSize,
            height: iconSize,
            opacity: bankOpacity,
            transform: `translateY(${bankTranslateY}px)`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke={primaryColor}
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ 
              width: "100%", 
              height: "100%", 
              filter: `drop-shadow(0 0 15px ${primaryColor})` // Added glow effect
            }}
          >
            {/* Bank Roof */}
            <path d="M3 9.5L12 4L21 9.5" fill={primaryColor} fillOpacity={0.1} />
            <path d="M3 9.5L12 4L21 9.5" />
            {/* Bank Cornice */}
            <rect x="2" y="10" width="20" height="3" rx="0.5" fill={primaryColor} />
            {/* Bank Columns */}
            <path d="M4 14V21" />
            <path d="M8 14V21" />
            <path d="M12 14V21" />
            <path d="M16 14V21" />
            <path d="M20 14V21" />
            {/* Bank Base */}
            <path d="M2 21H22" strokeWidth="2" />
          </svg>
        </div>

        {/* Text Container */}
        <h1
          style={{
            margin: 0,
            color: "#ffffff", // Changed from primaryColor to white
            fontSize: fontSize,
            fontWeight: 700,
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
            letterSpacing: "-0.02em",
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          Rentables
        </h1>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default BankCinematic;